package fraymus.workspace;
import com.jme3.bullet.*;
import com.jme3.bullet.objects.PhysicsRigidBody;
import com.jme3.bullet.collision.shapes.BoxCollisionShape;
import com.jme3.math.*;
import org.json.*;
import java.nio.file.Path;
import java.util.*;
/** A declared virtual gripper applies native wrenches; no pose/velocity writes after initialization. */
final class PosePhysics implements AutoCloseable {
 static final String VERSION="virtual-pose-gripper-034-v1";static final int MAX_TICKS=14400;
 final PhysicsSpace space;final JSONObject scene,plan,controller;final JSONArray events;final boolean orientation;
 final LinkedHashMap<String,PhysicsRigidBody> bodies=new LinkedHashMap<>();final List<String> dynamicIds=new ArrayList<>();
 int tick;double effort,torqueEffort,work,angularWork;Vector3f force=new Vector3f(),torque=new Vector3f();JSONArray ledger=new JSONArray(),contacts=new JSONArray();String actuated="";
 PosePhysics(JSONObject scene,JSONObject plan,Path nativeDir,boolean orientation,JSONObject restore,JSONArray events) throws Exception {
  PosePlan.verify(scene,plan);this.scene=scene;this.plan=plan;this.orientation=orientation;this.events=events;BulletRamp.load(nativeDir);space=new PhysicsSpace(PhysicsSpace.BroadphaseType.DBVT);space.setGravity(new Vector3f(0,(float)-scene.getDouble("gravityMps2"),0));space.setAccuracy((float)BulletRamp.DT);
  try{for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;String id=o.getString("id");double[] size=SpatialScene.vector(o.getJSONArray("size"),40);var b=new PhysicsRigidBody(new BoxCollisionShape((float)size[0]/2,(float)size[1]/2,(float)size[2]/2),(float)o.getDouble("massKg"));JSONObject pose=o;if(o.getDouble("massKg")>0){dynamicIds.add(id);if(restore!=null)pose=ContactPhysics.dynamic(restore.getJSONArray("bodies"),id);b.setDamping(.04f,.2f);b.setSleepingThresholds(0,0);b.setCcdMotionThreshold(.03f);b.setCcdSweptSphereRadius((float)Math.min(size[0],Math.min(size[1],size[2]))*.35f);}
    b.setPhysicsLocation(SpatialPhysics.vec(SpatialScene.vector(pose.getJSONArray("position"),30)));var q=pose.getJSONArray("rotation");b.setPhysicsRotation(new Quaternion(q.getFloat(0),q.getFloat(1),q.getFloat(2),q.getFloat(3)));b.setFriction(o.getFloat("friction"));b.setRestitution(o.getFloat("restitution"));if(restore!=null&&b.getMass()>0){b.setLinearVelocity(SpatialPhysics.vec(SpatialScene.vector(pose.getJSONArray("velocity"),100)));b.setAngularVelocity(SpatialPhysics.vec(SpatialScene.vector(pose.getJSONArray("angularVelocity"),100)));}space.addCollisionObject(b);bodies.put(id,b);}
   controller=restore==null?new JSONObject().put("phase","start").put("goal",0).put("stage",0).put("grippingId","").put("hold",0).put("enteredTick",0).put("windowTick",0).put("windowError",1e6).put("settle",0):new JSONObject(restore.getJSONObject("controller").toString());
   if(restore!=null){tick=restore.getInt("tick");effort=restore.getDouble("effortNs");torqueEffort=restore.getDouble("torqueEffortNms");work=restore.getDouble("workJ");angularWork=restore.getDouble("angularWorkJ");force=SpatialPhysics.vec(SpatialScene.vector(restore.getJSONArray("force"),100));torque=SpatialPhysics.vec(SpatialScene.vector(restore.getJSONArray("torque"),100));}
  }catch(Exception e){space.destroy();throw e;}
 }
 JSONObject body(String id){var b=bodies.get(id);var q=b.getPhysicsRotation();return new JSONObject().put("id",id).put("position",SpatialPhysics.json(b.getPhysicsLocation())).put("rotation",new JSONArray(new float[]{q.getX(),q.getY(),q.getZ(),q.getW()})).put("velocity",SpatialPhysics.json(b.getLinearVelocity())).put("angularVelocity",SpatialPhysics.json(b.getAngularVelocity())).put("initializationPoseWrites",1);}
 JSONArray states(){var out=new JSONArray();for(String id:dynamicIds)out.put(body(id));return out;}
 JSONObject snapshot(){var out=new JSONArray();for(Object raw:scene.getJSONArray("objects")){var o=new JSONObject(raw.toString());if(o.getDouble("massKg")>0){var b=body(o.getString("id"));for(String key:List.of("position","rotation","velocity","angularVelocity"))o.put(key,b.get(key));}out.put(o);}return new JSONObject().put("tick",tick).put("objects",out).put("gripping",!controller.getString("grippingId").isEmpty()).put("grippingId",controller.getString("grippingId")).put("controller",new JSONObject(controller.toString()));}
 boolean settled(){return Set.of("finished","failed").contains(controller.getString("phase"));}
 void event(String kind){events.put(new JSONObject().put("kind",kind).put("tick",tick).put("goal",controller.getInt("goal")).put("stage",controller.getInt("stage")).put("objectId",controller.getString("grippingId")).put("bodies",states()));}
 void fail(String reason){controller.put("phase","failed").put("reason",reason);event("failed");controller.put("grippingId","");}
 void resetWindow(){controller.put("enteredTick",tick).put("windowTick",tick).put("windowError",1e6).put("hold",0);}
 void control(){force=new Vector3f();torque=new Vector3f();actuated="";String phase=controller.getString("phase");if(phase.equals("start")){
   if(controller.getInt("goal")>=plan.getJSONArray("orderedTargets").length()){controller.put("phase","finished");event("finished");return;}
   var goal=plan.getJSONArray("orderedTargets").getJSONObject(controller.getInt("goal"));String id=goal.getString("objectId");var b=body(id);var p=b.getJSONArray("position");double h=plan.getDouble("liftHeightM");var target=goal.getJSONArray("positionM");var stages=new JSONArray().put(new JSONObject().put("position",new JSONArray(new double[]{p.getDouble(0),h,p.getDouble(2)})).put("rotation",b.getJSONArray("rotation"))).put(new JSONObject().put("position",new JSONArray(new double[]{p.getDouble(0),h,p.getDouble(2)})).put("rotation",goal.getJSONArray("rotation"))).put(new JSONObject().put("position",new JSONArray(new double[]{target.getDouble(0),h,target.getDouble(2)})).put("rotation",goal.getJSONArray("rotation"))).put(new JSONObject().put("position",target).put("rotation",goal.getJSONArray("rotation")));
   controller.put("stages",stages).put("stage",0).put("phase","move").put("grippingId",id);resetWindow();event("grab");phase="move";
  }
  if(phase.equals("release-settle")){controller.put("settle",controller.getInt("settle")+1);if(controller.getInt("settle")>=120){controller.put("goal",controller.getInt("goal")+1).put("phase","start");}return;}
  if(!phase.equals("move"))return;
  actuated=controller.getString("grippingId");var b=bodies.get(actuated);var current=body(actuated);var desired=controller.getJSONArray("stages").getJSONObject(controller.getInt("stage"));double[] dp=ObserverGeometry.sub(SpatialScene.vector(desired.getJSONArray("position"),10),SpatialScene.vector(current.getJSONArray("position"),30)),dr=PosePlan.rotationError(desired.getJSONArray("rotation"),current.getJSONArray("rotation"));double distance=ObserverGeometry.norm(dp),angle=ObserverGeometry.norm(dr);double[] v=SpatialScene.vector(current.getJSONArray("velocity"),100),omega=SpatialScene.vector(current.getJSONArray("angularVelocity"),100);
  boolean reached=distance<=.035&&ObserverGeometry.norm(v)<=.1&&(!orientation||angle<=Math.toRadians(2)&&ObserverGeometry.norm(omega)<=.1);controller.put("hold",reached?controller.getInt("hold")+1:0);
  if(controller.getInt("hold")>=12){event("stage-complete");if(controller.getInt("stage")==3){var before=body(actuated);event("release");events.getJSONObject(events.length()-1).put("before",before).put("after",body(actuated));controller.put("grippingId","").put("phase","release-settle").put("settle",0);actuated="";return;}controller.put("stage",controller.getInt("stage")+1);resetWindow();return;}
  double error=distance+(orientation?angle*.3:0);if(controller.getDouble("windowError")==1e6)controller.put("windowError",error);if(tick-controller.getInt("windowTick")>=480){if(controller.getDouble("windowError")-error<.005){fail("Measured pose progress stalled within the declared force/torque limits; no blind repeated actuation");actuated="";return;}controller.put("windowTick",tick).put("windowError",error);}
  if(tick-controller.getInt("enteredTick")>2880){fail("Pose stage exceeded12 simulated seconds");actuated="";return;}
  double speed=Math.min(.8,2.5*distance),angularSpeed=Math.min(1.2,3*angle),mass=b.getMass();double[] f=new double[3],t=new double[3];for(int k=0;k<3;k++){f[k]=mass*((distance<1e-12?0:dp[k]/distance*speed)-v[k])*8;t[k]=orientation?(angle<1e-12?0:dr[k]/angle*angularSpeed)-omega[k]:0;t[k]*=Math.min(1.4,mass*.35);}f[1]+=mass*scene.getDouble("gravityMps2");force=limit(SpatialPhysics.vec(f),plan.getJSONObject("intent").getDouble("forceLimitN"));torque=limit(SpatialPhysics.vec(t),plan.getJSONObject("intent").getDouble("torqueLimitNm"));
 }
 static Vector3f limit(Vector3f v,double cap){double n=v.length();return n>cap?v.mult((float)(cap/n)):v;}
 void step(){if(settled())return;if(tick>=MAX_TICKS){fail("Pose task exceeded60 simulated seconds");return;}var before=states();control();if(!actuated.isEmpty()){bodies.get(actuated).applyCentralForce(force);bodies.get(actuated).applyTorque(torque);}PhysicsSpace.setLocalThreadPhysicsSpace(space);space.update((float)BulletRamp.DT,0);tick++;
  var deltas=new JSONArray();double w=0,aw=0;for(String id:dynamicIds){var old=ContactPhysics.dynamic(before,id);var now=body(id);double[] dp=ObserverGeometry.sub(SpatialScene.vector(now.getJSONArray("position"),30),SpatialScene.vector(old.getJSONArray("position"),30));var q=now.getJSONArray("rotation");deltas.put(new JSONArray().put(id).put(new JSONArray(dp)).put(q));if(id.equals(actuated)){w=force.x*dp[0]+force.y*dp[1]+force.z*dp[2];double[] dr=PosePlan.rotationError(q,old.getJSONArray("rotation"));aw=torque.x*dr[0]+torque.y*dr[1]+torque.z*dr[2];}}
  effort+=ObserverGeometry.norm(SpatialScene.vector(SpatialPhysics.json(force),100))*BulletRamp.DT;torqueEffort+=ObserverGeometry.norm(SpatialScene.vector(SpatialPhysics.json(torque),100))*BulletRamp.DT;work+=w;angularWork+=aw;contacts=contacts();ledger.put(new JSONArray().put(tick).put(actuated).put(SpatialPhysics.json(force)).put(SpatialPhysics.json(torque)).put(w).put(aw).put(deltas));
 }
 JSONArray contacts(){var result=new JSONArray();var ids=new HashMap<Long,String>();for(var entry:bodies.entrySet())ids.put(entry.getValue().nativeId(),entry.getKey());for(long manifold:space.listManifoldIds()){String a=ids.get(com.jme3.bullet.collision.PersistentManifolds.getBodyAId(manifold)),b=ids.get(com.jme3.bullet.collision.PersistentManifolds.getBodyBId(manifold));if(a==null||b==null)continue;for(long p:com.jme3.bullet.collision.PersistentManifolds.listPointIds(manifold)){float n=com.jme3.bullet.collision.ManifoldPoints.getAppliedImpulse(p),d=com.jme3.bullet.collision.ManifoldPoints.getDistance1(p);if(n>1e-6&&d<=.015)result.put(new JSONObject().put("a",a).put("b",b).put("distanceM",d).put("normalImpulseNs",n));}}return result;}
 JSONObject sample(){return new JSONObject().put("tick",tick).put("timeS",tick*BulletRamp.DT).put("bodies",states()).put("force",SpatialPhysics.json(force)).put("torque",SpatialPhysics.json(torque)).put("effortNs",effort).put("torqueEffortNms",torqueEffort).put("workJ",work).put("angularWorkJ",angularWork).put("controller",new JSONObject(controller.toString())).put("contacts",new JSONArray(contacts.toString())).put("contactMethod","actual persistent native solver manifold with positive normal impulse");}
 JSONArray takeLedger(){var a=ledger;ledger=new JSONArray();return a;}
 @Override public void close(){space.destroy();}
}
